    static long calcMaxIncome(long a, long b, long c, long d, long e, long r) {
        // y 表示第二类套装数量，其上界同时受围巾、夹克、展位限制
        long upper = Math.min(b, Math.min(c, r / 2));

        long ans = 0;

        // 所有可能发生分段变化的位置
        long[] points = new long[] {
