import sys

def solve_one(a, b, c, d, e, r):
    # y 表示产品二的数量，上界由原材料B、原材料C、处理单元共同限制
    upper = min(b, c, r // 2)

    # 计算某个 y 下能获得的总利润
    def profit(y):
        if y < 0 or y > upper:
            return -1
        # 固定 y 后，x 取能取到的最大值
        x = min(a, c - y, r - 2 * y)
        if x < 0:
            return -1
        return d * x + e * y

    # 关键分界点候选
    points = [
        0,
        upper,
        c - a,
        r - c,
        (r - a) // 2
    ]

    ans = 0
    # 检查每个关键点附近的整数
    for p in points:
        for y in range(p - 2, p + 3):
            ans = max(ans, profit(y))

    return ans

def main():
